<script setup lang="ts">
definePageMeta({ middleware:'auth' })
const empty=()=>({phone:'',name:'',tier:'Silver' as 'Silver'|'Gold'|'Platinum',discountPercent:5});const form=reactive(empty());const search=ref('');const message=ref('')
const {data:members,refresh}=await useFetch<any[]>('/api/members',{default:()=>[]});const filtered=computed(()=>members.value.filter(m=>(m.name+m.phone).toLowerCase().includes(search.value.toLowerCase())))
watch(()=>form.tier,t=>form.discountPercent=t==='Silver'?5:t==='Gold'?10:15)
async function save(){message.value='';try{await $fetch('/api/members',{method:'POST',body:form});Object.assign(form,empty());await refresh()}catch(e:any){message.value=e?.data?.statusMessage||'บันทึกไม่สำเร็จ'}}
</script>
<template><div><AppNav/><main class="admin-page"><div class="page-title"><div><p class="eyebrow">CRM</p><h1>สมาชิก</h1></div><input v-model="search" class="search" placeholder="ค้นหาชื่อหรือเบอร์"></div><form class="panel form-row" @submit.prevent="save"><label>เบอร์โทร<input v-model="form.phone" required maxlength="10"></label><label>ชื่อ<input v-model="form.name" required></label><label>ระดับ<select v-model="form.tier"><option>Silver</option><option>Gold</option><option>Platinum</option></select></label><label>ส่วนลด %<input v-model.number="form.discountPercent" type="number" min="0" max="100"></label><button>เพิ่มสมาชิก</button><p v-if="message" class="error">{{message}}</p></form><div class="panel table-wrap"><table><thead><tr><th>สมาชิก</th><th>ระดับ</th><th>ส่วนลด</th><th>ยอดสะสม</th><th>แต้ม</th></tr></thead><tbody><tr v-for="m in filtered" :key="m.id"><td><strong>{{m.name}}</strong><small>{{m.phone}}</small></td><td>{{m.tier}}</td><td>{{m.discountPercent}}%</td><td>{{Number(m.totalSpent).toLocaleString()}} ฿</td><td>{{m.points}}</td></tr></tbody></table></div></main></div></template>
